H60_EXPLAINER = [
 ('Question', "Quark/gluon taggers respond to hadronisation beyond IRC-safe energy flow (claim D22). Do top taggers? When only the hadronisation changes so that a top jet carries more particles at the same jet mass, three-prong shape and W-pair mass, does the top score move, and in which direction?", None),
 ('Physics background', "IRC-safe observables (jet mass $m$, $\\tau_{32}=\\tau_3/\\tau_2$, the W-pair mass $m_W$, energy-flow polynomials) do not change when a particle splits collinearly or a very soft particle is added; the hadron count $N$ does, and depends on the hadronisation model. Top jets carry more particles than QCD jets of the same $p_T$, so a count-only classifier LR($N$) calls high-$N$ jets top. Among jets with the same IRC-safe substructure, extra soft particles are more typical of a radiation-rich QCD jet, so a classifier that reads $N$ at fixed substructure, GBDT(EFP+N), can move the other way.", None),
 ('Method', "Pythia 8.317, 14 TeV, Monash, all-hadronic $t\\bar t$ and QCD dijets, multi-parton interactions on; anti-$k_T$ $R=0.8$, $550<p_T<650$ GeV, $|\\eta|<2$; tops matched to their b, q, q′ within $\\Delta R<0.8$; particle level (no detector simulation). Reseeded per event so settings share the parton-level event. Settings (5k top + 5k QCD each): V0 nominal; V0b independent seeds (noise band); Hz± (the H54 string knobs, $N$ about ±9 %); $\\sigma$-only and $a$-only. Models: Top Landscape ParT, ParticleNet, LorentzNet, PFN, EFN; JetClass ParT_kin, PN_kin; weight-permuted ParT. Paired shift $\\Delta s=\\frac1n\\sum_j\\big[s_j^{\\rm variant}-s_j^{V0}\\big]$, $s=\\log p({\\rm top})/p({\\rm QCD})$; share of the count-at-fixed-substructure response $\\kappa_{\\rm EFP+N}=(\\Delta s_{\\rm net}-\\Delta s_{\\rm GBDT(EFP)})/(\\Delta s_{\\rm GBDT(EFP+N)}-\\Delta s_{\\rm GBDT(EFP)})$.", 'results/physics/h60_jet.png'),
 ('Result', "Hz+ on top jets: $N$ +8.6 %, $m$ −0.14 GeV, $\\tau_{32}$ −0.001, $m_W$ +0.02 GeV. EFN $+0.012\\,[-0.007,0.031]$, LR($N$) $+0.32$, GBDT(EFP+N) $-0.46$. ParT $-0.435\\,[-0.487,-0.380]$ ($\\kappa_{\\rm EFP+N}=0.94$), ParticleNet $-0.42$, LorentzNet $-0.82$, PFN $-0.58$, JetClass ParT_kin $-0.36$, PN_kin $-0.35$; Hz− reverses all of them (ParT $+0.49$). At the V0 threshold ParT's top efficiency goes 0.30 → 0.24. On QCD jets the sign depends on the architecture (ParT $-0.09$, ParticleNet $+0.22$).", 'results/physics/h60_shifts.png'),
 ('Checks', "Top Landscape test AUCs reproduce earlier values (ParT 0.9864). Permuted ParT $|\\Delta s|\\le0.03$; V0b noise band ≤ 0.07. The $\\sigma$-only and $a$-only settings move the EFN in opposite directions ($+0.05$, $-0.07$) while every network moves QCD-ward in both, so the effect is not a cancellation between knobs. The particle-level jets are far from the Delphes training jets (C2ST 0.98, mostly from $N$: 83 vs 55 particles). The verifier's count-only edits and detector proxy are in the next entry.", None),
 ('Physical significance', "Top taggers treat extra soft hadrons at fixed three-prong kinematics as evidence for QCD radiation, the opposite of what the overall particle count would suggest. Their top efficiency therefore depends on the hadronisation model, by an amount that at particle level is large (ε_S 0.30 → 0.24) and at detector level is not yet measured.", None),
]

H60V_EXPLAINER = [
 ('Question', "Is the H60 shift caused by the particle count (and not by other hadron-level changes), and does it survive when the jets look like the detector-level jets the networks were trained on?", None),
 ('Method', "Fresh seed 7272, 4,000 top + 4,000 QCD jets for V0 and Hz±. Count-only edits: (i) split — in each V0 top jet, split soft particles exactly collinearly (four-momentum and every IRC-safe quantity unchanged) until $N$ matches the paired Hz+ jet (on average 9.7 extra particles); (ii) merge — in each Hz+ jet, merge the nearest soft pairs back to the V0 count. The fraction of the Hz+ shift each edit reproduces or removes is reported. Detector proxy: neutral particles merged calorimeter-like, which brings $N$ to 49 / 38 (Top Landscape 55 / 44; C2ST 0.70).", None),
 ('Result', "Particle level reproduces: ParT $-0.454\\,[-0.516,-0.394]$, EFN $+0.003$. The split reproduces 0.84 [0.76, 0.95] of ParT's Hz+ shift (ParticleNet 0.75, PFN 0.81); the merge removes 1.19 [1.07, 1.35] (0.74–1.08 for the others). Under the detector proxy the count change falls to +6 % and ParT's shift to $-0.120\\,[-0.172,-0.068]$; Top ParticleNet, LorentzNet, PFN and PN_kin keep the QCD-ward sign ($-0.10$ to $-0.28$); JetClass ParT_kin shows none ($+0.007\\,[-0.039,0.057]$). On QCD jets split and merge do not reproduce the Hz+ shifts.", None),
 ('Checks', "Truth partons bit-identical in 100 % of pairs; padding masked; observables computed on the same massless inputs the networks see; working point from V0 tops. Weight-permuted ParT moves +0.03 to +0.10 under the edits, below the network effects. H60 ran with multi-parton interactions on, while the Top Landscape sample has them off.", None),
 ('Physical significance', "On top jets, extra particles at fixed substructure cause the QCD-ward shift: adding them alone reproduces it and removing them undoes it. How large this is for real detector-level top tagging is open: a crude detector model reduces it to about a quarter for ParT and removes it for one JetClass network.", None),
]

H61_EXPLAINER = [
 ('Question', "H60 found that top taggers lower their top score when Pythia's hadronisation adds particles at fixed jet mass, $\\tau_{32}$ and W-pair mass, but at particle level and with multi-parton interactions (MPI) on, while the networks were trained on Delphes detector-level jets with MPI off. Does the effect survive on detector-level jets made the way the training sample was made?", None),
 ('Physics background', "A detector does not see every hadron: Delphes keeps charged tracks and merges photons and neutral hadrons into calorimeter cells, so a top jet has about 55 reconstructed objects instead of about 80 hadrons. Soft extra hadrons from a hadronisation change can be absorbed into cells, so a particle-level count effect could shrink or vanish. IRC-safe quantities (jet mass, $\\tau_{32}$, energy-flow polynomials) are almost unchanged by the detector and by the hadronisation change.", None),
 ('Method', "Pythia 8.317, 14 TeV, Monash, MPI off; all-hadronic $t\\bar t$ and QCD dijets; every event reseeded so settings share the parton-level event. Stable particles passed through Delphes 3.5.1 with the ATLAS card; anti-$k_T$ $R=0.8$ on energy-flow objects, $550<p_T<650$ GeV, $|\\eta|<2$, tops matched to b, q, q′. Settings (5k top + 5k QCD each): V0 (Monash), V0r (V0 events, Delphes reseeded: detector-noise null), V0b (independent events), Hz± (string parameters that move the count by about ±7 %), $\\sigma$-only, $a$-only. Count-only edits on the Delphes jets: split (the $k$ softest objects of a V0 jet each replaced by two half-$p_T$ objects 0.01 apart, $k$ = the paired Hz+ count excess; mass and all IRC-safe quantities unchanged) and merge (the $k$ nearest soft pairs of the Hz+ jet combined). Metric: paired mean change in top log-odds $\\Delta s$, network minus EFN with bootstrap CIs, $\\kappa=\\Delta s_{\\rm net}/\\Delta s_{{\\rm GBDT(EFP+N)}}$, signal efficiency at the V0 50 % cut, Holm over 84 tests. Manifold check: C2ST of V0 against Top Landscape test jets.", None),
 ('Result', "Hz+ on top jets: $N$ +6.7 % (+4.2 objects), $m$ −0.36 GeV, $\\tau_{32}$ +0.001. EFN $+0.014\\,[-0.015,0.043]$, LR($N$) $+0.18$, GBDT(EFP+N) $-0.43$. Top ParT $-0.313\\,[-0.372,-0.253]$ (network − EFN $-0.33$, Holm $10^{-24}$, $\\kappa=0.73$), ParticleNet $-0.31$, LorentzNet $-0.42$, PFN $-0.33$, JetClass PN_kin $-0.20$, ParT_kin $-0.07$; Hz− reverses all. ParT's top efficiency at the V0 50 % cut: 0.50 → 0.46. The split alone reproduces 0.89 [0.75, 1.08] of ParT's shift (ParticleNet 1.11, PFN 1.05); the merge removes it (1.39). On QCD jets the sign still differs by architecture (ParT $-0.16$, ParticleNet $+0.17$).", 'results/physics/h61_shifts.png'),
 ('Checks', "Top Landscape test AUCs reproduce H60 exactly (ParT 0.9864); on the Delphes V0 jets every network keeps its accuracy (ParT 94.4 %). Delphes reseeding alone moves top scores by at most 0.024. Detector/particle jet $p_T$ response 0.994; 90 % of b, q, q′ partons have a constituent within $\\Delta R<0.2$. The C2ST against Top Landscape is 0.74 (target 0.6 not met): our jets have 13 % more, softer constituents, so sizes may differ on the exact training conditions.", 'results/physics/h61_jet.png'),
 ('Physical significance', "On the kind of input they were trained on, top taggers still read extra reconstructed objects at fixed three-prong kinematics as evidence for QCD: the effect is 0.51–0.74 of its particle-level size for the Top Landscape networks and is caused by the object count (H61v). Their top efficiency therefore depends on the hadronisation model at detector level, by a few percent of the tagged sample (ε_S 0.50 → 0.46 for a 7 % count change).", None),
]

